typedef enum { RES_OK, RES_ERR } res_tag;
typedef struct {
    res_tag tag;                                  /* read only the member the tag names */
    union { value_t value; err_t reason; } as;
} result_t;

static inline result_t res_ok(value_t v) { return (result_t){ .tag = RES_OK,  .as.value  = v }; }
static inline result_t res_err(err_t e)  { return (result_t){ .tag = RES_ERR, .as.reason = e }; }

result_t parse(const char *text);                 /* the caller switches on .tag first */
